using sv_66ae7962c9db4578998cefc18dfa2ed3.Auth;

namespace sv_66ae7962c9db4578998cefc18dfa2ed3.Client;

/// <summary>
/// Client-side (WebAssembly) AuthenticationStateProvider that reads persisted
/// auth state from PersistentComponentState, ensuring the user's identity
/// survives the Server → WebAssembly handoff.
/// </summary>
public sealed class PersistentAuthStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _defaultState =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authState;

    public PersistentAuthStateProvider(PersistentComponentState persistentState)
    {
        if (!persistentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) || userInfo is null)
        {
            _authState = _defaultState;
            return;
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, userInfo.Name),
            new(ClaimTypes.Email, userInfo.Email),
        };

        foreach (var role in userInfo.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, "FakeAuth");
        _authState = Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authState;
}

